"""Q-009 / X-RED-02 trade study: upper/lower reservoir options for the HYDRO_SET backup store (A-M-145). Writes docs-authority/HYDRO_SITING.md.
V = E / (rho g h eta); the head is the decision variable; structural numbers are loads, not designs (AWWA D100 for welded steel tanks,
ACI 350 for concrete environmental structures, penstock pressure = rho g h)."""
import json, os
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
g = json.load(open(os.path.join(ROOT, 'flow_graph/plant_flow_graph.json'))); N = {n['unit_id']: n for n in g['nodes']}
b = N['HYDRO_SET']['params']['backup_basis']; E = b['energy_kWh_bus']; eta = b['eta_turbine_generator']; RHO, G = 1000.0, 9.81
V = lambda h: E*3.6e6/(RHO*G*h*eta)
rows = []
for name, hs, note in (('A. Roof tank (present)', [18], 'roof carries the full water mass'),
                       ('B. Elevated tank on a tower', [25, 30, 40, 50], 'tower + foundation carry the water mass; AWWA D100 wind/seismic'),
                       ('C. Hillside upper reservoir', [50, 100, 200], 'lined pond at grade on site terrain; penstock down the slope; no elevated mass'),
                       ('D. Surface upper + deep-shaft / cavern lower reservoir', [100, 200, 300, 500], 'upper pond at grade; lower reservoir excavated; shaft depth = head')):
    for h in hs:
        v = V(h); m = v*RHO/1000; d = (4*v/(3.1416*10))**0.5 if name[0] in 'AB' else (v/5)**0.5   # A/B: 10 m deep cylinder dia; C/D: 5 m deep square side
        rows.append((name, h, v, m, ('%.1f m dia x 10 m' % d) if name[0] in 'AB' else ('%.1f m square x 5 m deep' % d), RHO*G*h/1e6, note))
md = ['# Pumped-hydro reservoir siting trade study', '', 'Document number: AQS-RED-002', 'Revision: B', 'Date: 2026-10-16',
      'Authority: AQS-PLAN-007 X-RED-02, open question Q-009 (owner decision). Generated by `docs-authority/_hydro_siting.py`. Study.', '',
      f'Backup store {E:.0f} kWh at the bus (NFPA 111 Class X, {b["class_hours"]} h x {b["critical_kW"]} kW, A-M-145), turbine-generator {eta}. Volume V = E/(rho g h eta); doubling the head halves the water. Friction in the penstock is not yet taken off the head.', '',
      '| Option | Head m | Water m3 | Water t (load) | Reservoir shape | Penstock / casing pressure MPa | Structural note |', '|---|---|---|---|---|---|---|']
md += [f'| {a} | {h} | {v:.0f} | {m:.0f} | {s} | {p:.2f} | {n} |' for a, h, v, m, s, p, n in rows]
md += ['', 'Reading the table:', '- A on the roof needs the roof to carry about 11,400 t; not credible on the hall structure.',
       '- B moves the mass onto its own tower: at 40 m about 5,100 t on a dedicated foundation (AWWA D100 tank, ASCE 7 wind and seismic).',
       '- C needs no elevated mass; it needs site relief of the stated head within penstock reach. Site survey decides.',
       '- D puts the head below grade: at 300 m the lower reservoir is about 690 m3 of excavation plus the shaft, with a 2.9 MPa casing and penstock. It is site-independent of terrain but depends on geology.',
       '', 'Owner decision (Q-009 closed 2026-10-16): none of A-D. The top floors of the building are the upper reservoir (a water tower within the building, a parametric form of B on the building structure) and CATCH_TANK is the lower reservoir. Sizing, loads, egress and roof PV are in AQS-BLD-014 (WATER_TOWER.md, A-M-187).']
open(os.path.join(ROOT, 'docs-authority/HYDRO_SITING.md'), 'w').write('\n'.join(md) + '\n'); print(len(rows), 'rows')
